CREATE TABLE whatsapp_product_sheets (id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, user_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, selected_product_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, version INT NOT NULL, status VARCHAR(16) NOT NULL, content JSON NOT NULL, approved_at DATETIME(6) NULL, created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6), PRIMARY KEY (id), UNIQUE KEY whatsapp_product_sheets_version_uq (selected_product_id,version), UNIQUE KEY whatsapp_product_sheets_owner_uq (id,user_id), KEY whatsapp_product_sheets_owner_idx (user_id,selected_product_id,status), CONSTRAINT whatsapp_product_sheets_status_ck CHECK (status IN ('draft','approved')), CONSTRAINT whatsapp_product_sheets_user_fk FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE, CONSTRAINT whatsapp_product_sheets_product_fk FOREIGN KEY (selected_product_id,user_id) REFERENCES selected_products(id,user_id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci